async function pageFunction(context) {
    const { $, request, log } = context;
    const category = $('.page-header h1').text().trim();
    const items = $('article.product_pod').map((i, el) => ({
        url: new URL($(el).find('h3 a').attr('href'), request.loadedUrl).href,
        title: $(el).find('h3 a').attr('title'),
        price: $(el).find('.price_color').text().trim(),
        category,
    })).get();
    log.info(category + ': ' + items.length + ' items');
    return items;
}
